import type { ExecutionContext, ExportedHandler, Response as WorkerResponse, Request as WorkerRequest } from '@cloudflare/workers-types';
// Generated by the OpenNext adapter after the full Next.js build.
// @ts-ignore build artifact
import handler from "./.open-next/worker.js";
import { LIVE_CLASSROOM_PATHS } from "./lib/study-workers/live-classroom";
import { verifyLiveAiGrant } from "./lib/study-workers/live-ai-transport";
import { studyTicket, guardStudyRequest } from "./lib/study-mcp/auth";
import { workersScope } from "./lib/study-workers/context";
import { installBuiltinSkills } from './lib/study-workers/skills';
import { isCoreJobRequest } from './lib/study-workers/job-auth';

async function serve(request: WorkerRequest, env: CloudflareEnv, context: Pick<ExecutionContext, 'waitUntil'>): Promise<WorkerResponse> {
  const path = new URL(request.url).pathname;
  // Service-binding requests also serve the public build assets directly.
  if (['GET', 'HEAD'].includes(request.method) && env.ASSETS && /^(?:\/_next\/static\/|\/(?:avatars|logos|vendor)\/|\/(?:openmaic-mark|logo-horizontal)\.png$)/.test(path)) return env.ASSETS.fetch(request);
  const alarm = await isCoreJobRequest(request, env.STUDY_MCP_SECRET);
  const maintenance = alarm && request.headers.get('x-study-maintenance') === 'true';
  let liveGrant: string | undefined;
  if (LIVE_CLASSROOM_PATHS.has(path)) {
    const value = request.headers.get('x-study-live-grant') ?? '';
    const grant = await verifyLiveAiGrant(value, env.STUDY_MCP_SECRET);
    const ticket = await studyTicket(request.headers, env.STUDY_MCP_SECRET);
    if (!grant || grant.purpose !== 'interaction' || !ticket || ticket.sub !== grant.sub || ticket.classroom_id !== grant.classroom)
      return Response.json({ error: '請從 STUDY 課堂發起互動', code: 'live_grant_required' }, { status: 403 }) as Response & WorkerResponse;
    liveGrant = value;
  }
  if (path === '/api/quiz-grade') return Response.json({ error: '請使用題目上的「請 AI 覆核」按鈕' }, { status: 409 }) as Response & WorkerResponse;
  return workersScope.run({ env, context, alarm, maintenance, liveGrant }, async () => {
    if (!alarm) {
      const denied = await guardStudyRequest(request, env.STUDY_MCP_SECRET);
      if (denied) return denied as Response & WorkerResponse;
    }
    // Prompt readers need files in this request's temporary filesystem.
    // Persistence and transport endpoints only read/write durable data.
    if (!/^\/api\/(?:persistence(?:\/|$)|study-mcp\/(?:tasks|status|session)(?:\/|$))/.test(path)) installBuiltinSkills();
    const response = await handler.fetch(request, env, context);
    if (!alarm && !['GET', 'HEAD'].includes(request.method) && response.ok && /^(?:\/api\/(?:generation-runs|generate-classroom|materials|agent|study-mcp\/(?:tasks|runs)))(?:\/|$)/.test(path)) {
      context.waitUntil(env.OPENMAIC_JOBS.getByName("coordinator-v1").wake().catch(error => console.error('Core scheduler wake failed; cron will recover durable work', error)));
    }
    return response;
  });
}

// Keep the v1 namespace addressable; all active scheduling uses the isolated Worker.
export class CoreJobs extends DurableObject<CloudflareEnv> {
  async alarm(): Promise<void> { await this.env.OPENMAIC_JOBS.getByName('coordinator-v1').wake(); }
}
const worker: ExportedHandler<CloudflareEnv> = {
  fetch: serve,
};
export default worker;
import { DurableObject } from 'cloudflare:workers';
